CREATE TABLE IF NOT EXISTS shop_orders (id text PRIMARY KEY, status text NOT NULL, email text NOT NULL, first_name text NOT NULL, last_name text NOT NULL, currency text NOT NULL, subtotal_cents integer NOT NULL, volume_discount_cents integer NOT NULL, promo_code text NOT NULL DEFAULT '', promo_discount_cents integer NOT NULL, total_cents integer NOT NULL, lines text NOT NULL, shipping text, payment_method text NOT NULL, whop_checkout_id text, whop_payment_id text, confirmation_sent_at text, created_at text NOT NULL);
